REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d15_back', 'Welcome back, Jun', '돌아온 준', 'office_desk', 'jun', 15, 15, '11:00', '12:15', NULL, 'Jun is back from Ridgeport and has reviewed your store ID fix. Praise his trip report, take his one comment well, explain how the dashboard work will go now that you are the technical lead, and look out for him: he is coughing.', '준이 리지포트에서 돌아와 당신의 매장 ID 수정 코드를 리뷰했습니다. 그의 출장 보고를 칭찬하고, 코멘트 하나를 잘 받아들이고, 당신이 기술 책임을 맡은 대시보드 일이 어떻게 진행될지 설명하고, 기침하는 그를 챙겨 주세요.', 0, 0, 1500, 'coworker,code-review,mentoring,week3', 'derek'),
  ('dk_d15_comp_time', 'Half a day off', '반나절 보상 휴가', 'office_manager', 'maya', 15, 15, '13:30', '17:30', NULL, 'Your week on call earned you half a day of comp time. Ask Maya for it, pick an afternoon that clashes with nothing, tell her how things are covered, and answer her questions about Jun and the dashboard.', '온콜 한 주로 반나절 보상 휴가가 생겼습니다. 마야에게 요청하고, 어떤 일정과도 겹치지 않는 오후를 고르고, 그동안 일이 어떻게 돌아갈지 말하고, 준과 대시보드에 대한 그녀의 질문에 답하세요.', 0, 0, 1510, 'manager,time-off,comp-time,week3', 'derek'),
  ('dk_d15_carl', 'Coffee for Carl', '칼에게 커피를', 'apartment_door', 'carl', 15, 15, '18:30', '20:30', NULL, 'On your way home, you stop at Maple Street Apartments to return Carl''s cooler from Saturday''s barbecue. Thank him, give him the gutter news, pay him back for the mower the way he asked, and ask him to keep an eye on Jun.', '퇴근길에 메이플 스트리트 아파트에 들러 토요일 바비큐 때 빌린 칼의 아이스박스를 돌려줍니다. 고맙다고 하고, 빗물받이 소식을 전하고, 그가 원한 방식으로 잔디 깎는 기계 수리에 보답하고, 준을 좀 챙겨 달라고 부탁하세요.', 0, 0, 1520, 'neighbor,thank-you,evening,week3', 'derek'),
  ('pr_d15_coffee', 'Treats for the team', '팀에 줄 간식', 'coffee_cart', 'nina', 15, 15, '07:00', '09:00', NULL, 'A gray Monday morning at Nina''s cart. Tell her about your weekend, get your usual, and pick up pastries for the team: you promised them a celebration.', '흐린 월요일 아침, 니나의 카트입니다. 주말 얘기를 하고, 늘 마시던 걸 주문하고, 팀에 줄 빵도 사세요. 축하하자고 약속했으니까요.', -28, 10, 1500, 'food,order,coffee,small-talk,week3', 'priya'),
  ('pr_d15_standup', 'Jun is back: Monday standup', '준이 돌아왔다: 월요일 스탠드업', 'office_desk_team', 'derek', 15, 15, '09:00', '11:00', NULL, 'The first standup since the contract was signed. Welcome Jun back from Ridgeport, keep his trip report short, tell him where his receipts go, thank Derek for covering a bug, and finish on time.', '계약 체결 후 첫 스탠드업입니다. 리지포트에서 돌아온 준을 맞이하고, 출장 보고는 짧게 받고, 영수증을 어디에 내는지 알려 주고, 버그를 대신 맡아 준 데릭에게 고마움을 전하고, 제시간에 끝내세요.', 0, 0, 1510, 'meeting,standup,facilitation,week3', 'priya'),
  ('pr_d15_applicants', 'The first applicants', '첫 지원자들', 'office_hr', 'linda', 15, 15, '14:30', '17:00', NULL, 'The developer job went up this morning, and applications are already coming in. Agree with Linda on who screens what, answer a question about remote work, ask about the contractor, and find time for the first calls.', '개발자 채용 공고가 오늘 아침에 올라갔고, 벌써 지원서가 들어오고 있습니다. 누가 무엇을 거를지 린다와 정하고, 재택근무 질문에 답하고, 계약직에 대해 묻고, 첫 통화 일정을 잡으세요.', 0, 0, 1520, 'hr,hiring,office,week3', 'priya');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d15_back', 1, NULL, 'Monday, gray and cool. The standup is over, and you stop by Jun''s desk. He''s rubbing his eyes.', '흐리고 선선한 월요일입니다. 스탠드업이 끝나고 준의 자리에 들릅니다. 그가 눈을 비비고 있습니다.', 'Hey, Derek. Sorry, I''m a bit slow today. Two days of meetings with Greg, and I''m still catching up on sleep.', '안녕하세요, 데릭. 죄송해요, 오늘 좀 멍해요. 그렉이랑 이틀 내내 회의하고 아직 잠이 모자라요.', 'Welcome him back, and tell him how his trip report in the standup came across.', '돌아온 걸 반겨 주고, 스탠드업에서 한 출장 보고가 어땠는지 말해 주세요.', '[]', 'Welcome back! You nailed the trip report this morning. Everyone was impressed.', '잘 돌아왔어요! 아침 출장 보고 완벽했어요. 다들 감탄했어요.', '["Welcome back. Your trip report ran a little long, though. Keep it shorter next time.","Welcome back! Great trip report. Too bad Greg still hasn''t signed, though.","Welcome back! You look terrible. Did you get any sleep at all on the flight?"]', '["잘 돌아왔어요. 근데 출장 보고가 좀 길었어요. 다음엔 짧게 해요.","잘 돌아왔어요! 출장 보고 좋았어요. 그렉이 아직 사인 안 한 게 아쉽지만요.","잘 돌아왔어요! 얼굴이 말이 아니네요. 비행기에서 잠은 좀 잤어요?"]', '["Oh. Sorry. I guess I got a little carried away.","Hasn''t signed? He signed on Friday, Derek. I called you!","Not really. Thanks for noticing, I guess."]', '["아. 죄송해요. 좀 신이 났었나 봐요.","사인 안 했다고요? 금요일에 했어요, 데릭. 전화도 드렸잖아요!","별로요. 알아봐 주셔서... 고맙네요."]', NULL, 'Thanks! I was nervous, but it''s easy when the news is good.', '고마워요! 떨렸는데, 좋은 소식이라 쉬웠어요.'),
  ('dk_d15_back', 2, NULL, 'He pulls up your pull request for the store ID bug. There is one comment on it.', '그가 매장 ID 버그를 고친 당신의 풀 리퀘스트를 띄웁니다. 코멘트가 하나 달려 있습니다.', 'I went through your fix. It looks good. Just one thing: the tests use made-up IDs. Dana sent us the real data from the seven stores on Friday.', '수정한 거 봤어요. 좋아요. 하나만요. 테스트가 지어낸 ID를 쓰더라고요. 데이나가 금요일에 매장 일곱 곳의 실제 데이터를 보내 줬어요.', 'Agree it is a fair point, and ask him to check the fix against the real data before the date you gave Dana.', '타당한 지적이라고 인정하고, 데이나에게 약속한 날짜 전에 실제 데이터로 수정을 확인해 달라고 하세요.', '[]', 'Good catch. That''s why we told Dana Wednesday. Could you run it on her data today?', '잘 잡았어요. 그래서 데이나한테 수요일이라고 한 거예요. 오늘 그 데이터로 돌려 봐 줄래요?', '["Good catch. That''s why we told Dana Friday. Could you run it on her data this week?","No need. The fix is simple, so fake IDs are good enough. Let''s just merge it.","I tested it plenty, Jun. If you don''t trust it, go ahead and run it yourself."]', '["잘 잡았어요. 그래서 데이나한테 금요일이라고 한 거예요. 이번 주 안에 그 데이터로 돌려 봐 줄래요?","그럴 필요 없어요. 수정이 간단해서 가짜 ID로 충분해요. 그냥 머지해요.","충분히 테스트했어요, 준. 못 믿겠으면 직접 돌려 봐요."]', '["Friday? I thought Priya told her Wednesday.","Hmm. But those seven stores are the whole problem.","Sorry, I didn''t mean it that way."]', '["금요일이요? 프리야가 수요일이라고 한 줄 알았는데요.","음. 근데 문제가 바로 그 일곱 매장인데요.","죄송해요, 그런 뜻은 아니었어요."]', NULL, 'Sure. If it passes, I''ll approve it this afternoon.', '그럴게요. 통과하면 오후에 승인할게요.'),
  ('dk_d15_back', 3, NULL, 'Jun lowers his voice a little.', '준이 목소리를 조금 낮춥니다.', 'Maya said you''re the technical lead on the dashboard now. Congrats! So... do I report to you now?', '마야가 이제 데릭이 대시보드 기술 책임이라고 하던데요. 축하해요! 그럼... 이제 데릭한테 보고하는 거예요?', 'Explain how the two of you will work on it, without sounding like his new boss.', '새 상사처럼 들리지 않게, 둘이 이 일을 어떻게 할지 설명하세요.', '[]', 'No, Maya''s still your manager. I''ll help with the big calls, but you''ll build most of it.', '아니요, 매니저는 여전히 마야예요. 큰 결정은 제가 돕고, 만드는 건 대부분 준이 해요.', '["Yes, starting today you report to me. Maya made it official in our meeting first thing this morning.","Sort of. You''ll build most of it, but I''ll review every single commit before it goes in.","No, but the deadline''s tight, so I''ll build most of it. You can help with the testing."]', '["네, 오늘부터 저한테 보고해요. 아침 회의에서 마야가 공식적으로 정했어요.","비슷해요. 만드는 건 대부분 준이 하지만, 커밋은 하나하나 들어가기 전에 제가 다 볼 거예요.","아니요, 근데 마감이 빠듯해서 대부분 제가 만들 거예요. 준은 테스트를 도와줘요."]', '["Oh. Really? Maya didn''t mention that part.","Every commit? Okay... I''ll try not to slow you down.","Oh. I was hoping to build it. I know their data now."]', '["아. 정말요? 마야는 그 얘긴 안 했는데요.","커밋 하나하나요? 네... 늦어지지 않게 해 볼게요.","아. 제가 만들고 싶었는데요. 이제 그쪽 데이터도 알고요."]', NULL, 'Got it. Honestly, that''s a relief. I can''t wait to start.', '알겠어요. 솔직히 마음이 놓이네요. 빨리 시작하고 싶어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d15_back', 4, NULL, 'Jun coughs into his elbow, then again.', '준이 팔꿈치에 대고 기침을 하더니, 또 합니다.', 'Sorry. It''s just the dry air on the plane. I''m fine, really.', '죄송해요. 비행기 안 공기가 건조해서 그래요. 정말 괜찮아요.', 'Look out for him: tell him not to push himself, and what to do if he feels worse.', '그를 챙겨 주세요. 무리하지 말라고 하고, 더 안 좋아지면 어떻게 할지 말해 주세요.', '[]', 'Take it easy today. If you feel worse tomorrow, stay home. We''ll manage.', '오늘은 무리하지 마요. 내일 더 안 좋으면 집에서 쉬어요. 우리가 알아서 할게요.', '["Push through for now. Phase one kicks off next week, so nobody can be out.","Okay, but sit a little farther away. I can''t afford to get sick this week.","Go home now. I''ll finish testing my fix and approve it myself."]', '["일단 버텨 봐요. 다음 주에 1단계 시작이라 아무도 빠지면 안 돼요.","알겠어요, 근데 좀 떨어져 앉아요. 이번 주엔 저 아프면 안 돼요.","지금 집에 가요. 테스트는 제가 마저 하고 제 수정은 제가 승인할게요."]', '["Right. I''ll be fine. I hope.","Oh. Sure. I''ll keep my distance.","Approve your own fix? No, no. I can do the testing."]', '["그렇죠. 괜찮을 거예요. 아마도요.","아. 네. 떨어져 있을게요.","직접 승인한다고요? 아니에요. 테스트는 제가 할 수 있어요."]', NULL, 'Thanks, Derek. I''ll grab some tea from the kitchen and take it slow.', '고마워요, 데릭. 탕비실에서 차 한 잔 들고 천천히 할게요.'),
  ('dk_d15_comp_time', 1, NULL, 'Monday afternoon. Linda said your week on call earns you half a day off, and Maya approves it. Maya''s door is open.', '월요일 오후입니다. 린다 말로는 온콜 한 주에 반일 휴가가 나오고, 승인은 마야가 합니다. 마야의 방문이 열려 있습니다.', 'Derek, come on in. What''s up?', '데릭, 들어와요. 무슨 일이에요?', 'Check that she has a moment, and say what you''ve come about.', '잠깐 시간이 되는지 묻고, 무슨 일로 왔는지 말하세요.', '[]', 'Got a minute? I''d like to use the comp time from my week on call.', '잠깐 괜찮으세요? 온콜 주간 보상 휴가를 쓰고 싶어서요.', '["I''m taking Friday afternoon off. Linda already said it''s fine.","Got a minute? I''d like comp time for the interviews I''m doing this week.","Sorry to bother you. Is there any way I could take a whole day off soon?"]', '["금요일 오후에 쉴게요. 린다가 이미 괜찮다고 했어요.","잠깐 괜찮으세요? 이번 주에 하는 면접에 대해 보상 휴가를 받고 싶어서요.","귀찮게 해서 죄송해요. 조만간 하루 통째로 쉴 수 있을까요?"]', '["Linda did? Time off goes through me, Derek.","Interviews are part of the job. They don''t earn comp time.","A whole day? What''s the occasion?"]', '["린다가요? 휴가는 저를 거쳐야 해요, 데릭.","면접은 업무의 일부예요. 보상 휴가는 안 나와요.","하루 종일이요? 무슨 일 있어요?"]', NULL, 'Sure. Linda mentioned it. Half a day, right?', '그럼요. 린다한테 들었어요. 반나절이죠?'),
  ('dk_d15_comp_time', 2, NULL, 'Maya opens the team calendar.', '마야가 팀 달력을 엽니다.', 'When were you thinking? The next couple of weeks are pretty full.', '언제로 생각해요? 앞으로 2주가 꽤 꽉 찼는데요.', 'Suggest an afternoon this week that won''t get in the way of anything you''ve already agreed to.', '이미 하기로 한 일에 방해되지 않는, 이번 주 오후 하나를 제안하세요.', '[]', 'How about Friday afternoon? My interviews are Tuesday and Thursday, so Friday''s clear.', '금요일 오후는 어때요? 면접이 화요일이랑 목요일이라 금요일은 비어 있어요.', '["How about Thursday afternoon? My interviews are Tuesday and Friday, so Thursday''s clear.","How about all of Friday? I''ll make up the other half some other time.","How about next Monday afternoon? Things should be quiet once the week starts."]', '["목요일 오후는 어때요? 면접이 화요일이랑 금요일이라 목요일은 비어 있어요.","금요일 하루 다 쉬면 어때요? 나머지 반나절은 나중에 채울게요.","다음 주 월요일 오후는 어때요? 주 초엔 한가할 테니까요."]', '["Thursday? Linda has you on the panel that day.","Half a day, Derek. Not a whole one.","Next Monday? That''s when phase one kicks off."]', '["목요일이요? 린다가 그날 면접관으로 넣어 놨던데요.","반나절이에요, 데릭. 하루가 아니고요.","다음 주 월요일이요? 그날 1단계 시작이잖아요."]', NULL, 'Friday afternoon works for me.', '금요일 오후 좋아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d15_comp_time', 3, NULL, 'She types it in, then looks up.', '그녀가 입력하고 고개를 듭니다.', 'And if something breaks on Friday afternoon?', '그런데 금요일 오후에 뭔가 터지면요?', 'Reassure her: you''re not on call this week, and you''ll make sure nothing open depends on you alone.', '그녀를 안심시키세요. 이번 주엔 온콜이 아니고, 진행 중인 일이 당신 혼자에게만 달려 있지 않게 하겠다고요.', '[]', 'I''m not on call this week, so that''s covered. And I''ll leave notes on anything still open.', '이번 주엔 온콜이 아니라 그건 괜찮아요. 그리고 남은 일은 메모로 정리해 둘게요.', '["Honestly, nothing ever breaks on a Friday afternoon. Trust me, it''ll be totally fine.","I''m on call this week, but I''ll keep my phone on me, so I can still jump in if anything happens.","That''s the on-call person''s problem. They can handle it without me for once."]', '["솔직히 금요일 오후엔 뭐가 터진 적이 없어요. 믿어 보세요, 아무 일 없을 거예요.","이번 주에 온콜이긴 한데, 휴대폰은 들고 있을 테니 무슨 일 생기면 바로 들어올 수 있어요.","그건 온콜 담당자 문제죠. 한 번쯤은 저 없이 처리하게 두면 돼요."]', '["Famous last words, Derek.","If you''re on call, you can''t really be off. Let''s rethink.","That''s a teammate you''re talking about."]', '["그런 말이 꼭 사고를 부르던데요, 데릭.","온콜이면 제대로 쉬는 게 아니잖아요. 다시 생각해 보죠.","지금 동료 얘기 하는 거예요."]', NULL, 'Good. Put the request in the system, and I''ll approve it today.', '좋아요. 시스템에 신청 올려요. 오늘 승인할게요.'),
  ('dk_d15_comp_time', 4, NULL, 'Maya leans back in her chair.', '마야가 의자에 등을 기댑니다.', 'While you''re here: how''s Jun doing? First day back after a big trip.', '온 김에요. 준은 어때요? 큰 출장 다녀와서 첫날이잖아요.', 'Be honest: the work side is going well, but you''re a little worried about his health. Say what you told him.', '솔직하게 말하세요. 일은 잘되고 있지만 건강이 조금 걱정됩니다. 그에게 뭐라고 했는지도 말하세요.', '[]', 'He''s doing well, but he''s worn out and coughing. I told him to stay home if it gets worse.', '잘하고 있는데, 지쳤고 기침을 해요. 더 안 좋아지면 집에서 쉬라고 했어요.', '["He''s full of energy. The trip didn''t slow him down one bit, and he''s already back to full speed.","Honestly, he''s slow today. I''d keep an eye on his work this week if I were you.","He''s sick, so I told him to take tomorrow off. I hope that''s okay with you."]', '["기운이 넘쳐요. 출장 때문에 조금도 지치지 않았고, 벌써 제 속도로 돌아왔어요.","솔직히 오늘 좀 느려요. 저라면 이번 주에 준이 하는 일을 지켜보겠어요.","아파서 내일은 쉬라고 했어요. 괜찮으시죠?"]', '["Really? He looked pretty tired in the standup.","That''s a little harsh. He just got back from a big trip.","That''s my call, Derek. But let''s see how he feels."]', '["정말요? 스탠드업 때 꽤 피곤해 보이던데요.","좀 가혹하네요. 큰 출장에서 막 돌아왔잖아요.","그건 제가 정할 일이에요, 데릭. 그래도 상태는 지켜보죠."]', NULL, 'Good call. I''ll check in with him before he heads home.', '잘했어요. 퇴근 전에 제가 한번 들여다볼게요.'),
  ('dk_d15_comp_time', 5, NULL, 'Maya glances at the whiteboard: "Summit dashboard, phase one: Nov 1."', '마야가 화이트보드를 흘끗 봅니다. "서밋 대시보드 1단계: 11월 1일".', 'Last thing. November 1st for the dashboard. Is that still realistic?', '마지막으로요. 대시보드 11월 1일. 아직 현실적이에요?', 'Give her an honest answer as technical lead, and promise she won''t be caught off guard.', '기술 책임자로서 솔직하게 답하고, 그녀가 뒤늦게 알고 놀랄 일은 없게 하겠다고 약속하세요.', '[]', 'It''s tight, but doable if the scope holds. If anything slips, you''ll hear it from me first.', '빠듯하지만 범위만 그대로면 할 수 있어요. 뭐라도 밀리면 제가 제일 먼저 말씀드릴게요.', '["Easily. We''ll probably have it done a week early, so go ahead and tell Priya that today.","It''s tight, but doable if the scope holds. Luckily, it''s not due until the middle of December.","Hard to say yet. Ask me again after the kickoff next week. I will know a lot more by then."]', '["여유 있어요. 아마 일주일 일찍 끝날 테니 오늘 프리야한테 그렇게 말해도 돼요.","빠듯하지만 범위만 그대로면 할 수 있어요. 다행히 12월 중순까지잖아요.","아직은 뭐라 하기 어려워요. 다음 주 킥오프 끝나고 다시 물어봐 주세요. 그땐 훨씬 더 알 거예요."]', '["A week early? Let''s not promise Priya that just yet.","December? It''s due November 1st, Derek.","I need something to give Priya before then."]', '["일주일 일찍이요? 프리야한테 그 약속은 아직 하지 말죠.","12월이요? 11월 1일까지예요, 데릭.","그 전에 프리야한테 뭐라도 말해 줘야 해요."]', NULL, 'That''s all I need to hear. Enjoy your Friday afternoon. You''ve earned it.', '그거면 충분해요. 금요일 오후 잘 쉬어요. 그럴 자격 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d15_carl', 1, NULL, 'Evening, gray but dry. On Saturday Carl sent you home with leftovers in his cooler. You bring it back, with a bag of coffee beans from Nina''s cart. Carl is sitting on the front steps.', '흐리지만 비는 오지 않는 저녁입니다. 토요일에 칼이 남은 음식을 아이스박스에 담아 보내 줬습니다. 그걸 돌려주러 왔습니다. 니나의 카트에서 산 원두 한 봉지도 들고요. 칼은 현관 계단에 앉아 있습니다.', 'Well, look who it is! What brings you to my neck of the woods on a Monday?', '이게 누구야! 월요일에 웬일로 우리 동네까지 왔나?', 'Say why you came by, and thank him for the party.', '들른 이유를 말하고, 파티에 대해 고맙다고 하세요.', '[]', 'I came to return your cooler. Thanks again for Saturday. I had a great time.', '아이스박스 돌려드리러 왔어요. 토요일엔 다시 한번 고마웠어요. 정말 즐거웠어요.', '["I came to return your cooler. Thanks again for Sunday. I had a great time.","Just dropping off your cooler. I can''t stay long, Carl. I''ve got a lot going on.","I came by to check on Jun. Is he home yet? He looked pretty tired today."]', '["아이스박스 돌려드리러 왔어요. 일요일엔 다시 한번 고마웠어요. 정말 즐거웠어요.","아이스박스만 놓고 갈게요. 오래 못 있어요. 할 일이 많아서요.","준 좀 보러 왔어요. 집에 왔어요? 오늘 꽤 피곤해 보였거든요."]', '["Sunday? It poured all Sunday. The barbecue was Saturday!","Well, hello to you too. Busy day?","Haven''t seen him come in yet. Is that my cooler under your arm?"]', '["일요일? 일요일엔 비가 쏟아졌잖나. 바비큐는 토요일이었지!","그래, 나도 반갑네. 바쁜 날이었나 보군?","아직 들어오는 건 못 봤네. 옆구리에 낀 그거 내 아이스박스 아닌가?"]', NULL, 'Glad you came. Jun had three helpings of my ribs, you know.', '와 줘서 좋았네. 준은 내 갈비를 세 번이나 가져다 먹었다네.'),
  ('dk_d15_carl', 2, NULL, 'Carl takes the cooler and sets it by the door.', '칼이 아이스박스를 받아 문 옆에 내려놓습니다.', 'Say, did that gutter of yours hold up in Sunday''s rain?', '그런데 자네 빗물받이는 일요일 비에 잘 버텼나?', 'Tell him how it went, and give credit where it''s due.', '어떻게 됐는지 말하고, 공을 돌릴 사람에게 돌리세요.', '[]', 'Not a drop at the front door all day. That was all you, Carl.', '현관 앞에 하루 종일 한 방울도 안 떨어졌어요. 다 칼 덕분이에요.', '["Not a single drip all day. Turns out I''m pretty handy after all.","It held up fine, but honestly, I never got around to clearing it.","It was fine. Honestly, I could have paid someone to do it anyway."]', '["하루 종일 한 방울도 안 샜어요. 저 생각보다 손재주가 있나 봐요.","잘 버텼어요. 근데 솔직히 결국 청소는 못 했어요.","괜찮았어요. 솔직히 그냥 사람 불러서 시켜도 됐을 거예요."]', '["Ha! And who held the ladder, again?","Never cleared it? I held the ladder for you myself!","Paid someone? Ninety bucks for twenty minutes? Ha!"]', '["하! 그래서 사다리는 누가 잡아 줬더라?","안 치웠다고? 내가 직접 사다리를 잡아 줬는데!","돈 주고? 20분짜리 일에 90달러? 하!"]', NULL, 'Ha! You did the climbing. I just held the ladder.', '하! 올라간 건 자네였지. 난 사다리만 잡았을 뿐이야.'),
  ('dk_d15_carl', 3, NULL, 'You hand him the bag of coffee beans. He sniffs it and raises an eyebrow.', '원두 봉지를 건넵니다. 그가 냄새를 맡더니 눈썹을 치켜올립니다.', 'What''s this for? It''s not my birthday.', '이건 뭐 하러? 내 생일도 아닌데.', 'Remind him what he asked for in return for fixing your mower.', '잔디 깎는 기계를 고쳐 준 대가로 그가 뭘 원했는지 상기시켜 주세요.', '[]', 'You told me to buy you a coffee sometime. I figured I''d get you a whole bag.', '언제 커피나 한 잔 사라고 하셨잖아요. 그래서 아예 한 봉지 사 왔어요.', '["You told me to buy you lunch sometime. So I figured coffee beans would do instead.","It''s for the eleven dollars you spent on the gasket. Now we''re even, okay?","Nina gave it to me for free, so I figured I''d just pass it along to you."]', '["언제 점심이나 사라고 하셨잖아요. 그래서 원두로 대신하면 되겠다 싶었어요.","개스킷에 쓰신 11달러 대신이에요. 이제 빚진 거 없는 거예요, 알았죠?","니나가 공짜로 준 건데, 그냥 칼한테 넘겨드리려고요."]', '["Lunch? I said coffee. But I''m not complaining.","Even? I wasn''t keeping score, Derek.","A hand-me-down, huh? Well, it still smells good."]', '["점심? 난 커피라고 했는데. 그래도 불만은 없네.","빚? 난 셈 같은 거 안 했네, 데릭.","얻은 걸 넘겨주는 거구먼? 그래도 냄새는 좋네."]', NULL, 'From Nina''s cart? Now that''s a fair trade. Best coffee in Fairview.', '니나네 카트 거야? 이거면 공정한 거래지. 페어뷰에서 제일가는 커피니까.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d15_carl', 4, NULL, 'Carl tucks the bag under his arm and nods toward the building.', '칼이 봉지를 옆구리에 끼고 건물 쪽으로 고개를 까딱합니다.', 'Say, how is the young fella doing? I saw him at the bus stop this morning. He looked like something the cat dragged in.', '그런데 그 젊은 친구는 어떤가? 아침에 버스 정류장에서 봤는데, 영 몰골이 말이 아니더군.', 'Tell him what you noticed about Jun today, and ask a neighborly favor for him.', '오늘 본 준의 상태를 말하고, 이웃으로서 준을 위해 부탁을 하나 하세요.', '[]', 'He''s worn out and coughing. Could you keep an eye on him? You''re in the same building.', '많이 지쳤고 기침도 해요. 좀 살펴봐 주실래요? 같은 건물에 사시잖아요.', '["Oh, he''s fine. Kids his age bounce right back in no time. Don''t you worry about him at all.","He''s sick. Could you tell him I said he''s not allowed to come in tomorrow?","He''s worn out from his trip overseas. Could you keep an eye on him for me?"]', '["아, 괜찮아요. 그 나이 땐 금방 회복해요. 전혀 걱정 안 하셔도 돼요.","아파요. 내일 출근하면 안 된다고 제가 그랬다고 전해 주실래요?","해외 출장 때문에 지쳤어요. 저 대신 좀 살펴봐 주실래요?"]', '["Hmm. He didn''t look fine to me.","Me? You''re his buddy. Tell him yourself, Derek.","Overseas? I thought he flew to Ridgeport."]', '["흠. 내 눈엔 괜찮아 보이지 않던데.","나더러? 자네가 그 친구 버디잖나. 직접 말하게, 데릭.","해외? 리지포트에 갔다 온 줄 알았는데."]', NULL, 'Will do. I''ll bring him a bowl of my chicken soup tonight. Cures anything.', '그러지. 오늘 밤에 내 닭고기 수프 한 그릇 갖다주겠네. 뭐든 낫게 하는 수프야.'),
  ('pr_d15_coffee', 1, NULL, 'Monday morning. Gray skies over Lake Avenue, but no rain today.', '월요일 아침입니다. 레이크 애비뉴 하늘은 흐리지만 오늘은 비가 오지 않습니다.', 'Morning, Priya! You look rested for a Monday. Good weekend?', '좋은 아침이에요, 프리야! 월요일치고 얼굴이 좋네요. 주말 잘 보냈어요?', 'Tell her yes: you kept work out of your weekend. Mention Saturday''s barbecue.', '네, 주말엔 일을 멀리했다고 하세요. 토요일 바비큐 얘기도 하세요.', '[]', 'It was great. I didn''t open my laptop once, and I went to a barbecue on Saturday.', '정말 좋았어요. 노트북을 한 번도 안 열었고, 토요일엔 바비큐에 갔어요.', '["It was great. I didn''t open my laptop once, and I went to a barbecue on Sunday.","Not bad. I only answered work emails for an hour or two, then went to a barbecue.","It was great, thanks. Hey, is it supposed to rain again at some point later today?"]', '["정말 좋았어요. 노트북을 한 번도 안 열었고, 일요일엔 바비큐에 갔어요.","나쁘지 않았어요. 업무 메일에 한두 시간만 답하고, 바비큐에 갔어요.","좋았어요, 고마워요. 그런데 오늘 이따가 비가 또 온대요?"]', '["On Sunday? In that rain? Brave.","An hour or two? Priya, that''s not a weekend off.","Nope, dry all day. But you didn''t answer me. What''d you do?"]', '["일요일에요? 그 비에요? 용감하네요.","한두 시간이요? 프리야, 그건 쉰 게 아니에요.","아뇨, 종일 안 와요. 그런데 대답을 안 했네요. 뭐 했어요?"]', NULL, 'Good for you! The usual, then. Medium oat latte, extra shot.', '잘했어요! 그럼 늘 마시던 걸로요. 귀리 우유 라테 미디엄, 샷 추가.'),
  ('pr_d15_coffee', 2, NULL, 'On Friday, you promised Jun you''d celebrate the contract on Monday.', '금요일에 준에게 월요일에 계약을 축하하자고 약속했습니다.', 'Anything else this morning?', '오늘 아침엔 더 필요한 거 있어요?', 'You want to bring something for the team. Find out what baked goods she has today.', '팀에 뭔가 가져가고 싶습니다. 오늘은 어떤 빵이 있는지 알아보세요.', '[]', 'Yes, I''d like to bring something for my team. What pastries do you have today?', '네, 팀에 뭘 좀 가져가고 싶어서요. 오늘은 어떤 빵이 있어요?', '["No, that''s all for me, thanks. Just the latte this morning, please.","Yes, something for my team. Could you bring a tray of pastries to our office?","Yes, my team''s celebrating today. Do you have a whole cake I could pick up later?"]', '["아뇨, 그거면 돼요, 고마워요. 오늘 아침엔 라테만 주세요.","네, 팀에 줄 거요. 빵 한 쟁반을 저희 사무실로 갖다주실 수 있어요?","네, 오늘 팀이 축하할 일이 있어서요. 이따 가져갈 홀케이크 하나 있어요?"]', '["Just the latte, then. You sound like you''re forgetting something.","Bring it over? It''s just me and this cart, Priya. I can''t leave it.","A whole cake? On a cart this size? I wish."]', '["그럼 라테만요. 뭔가 잊어버린 사람 같은데요.","갖다 달라고요? 저랑 이 카트뿐이에요, 프리야. 자리를 못 비워요.","홀케이크요? 이만한 카트에서요? 그럼 좋겠네요."]', NULL, 'Blueberry muffins and butter croissants, fresh this morning.', '블루베리 머핀이랑 버터 크루아상이요. 오늘 아침에 나온 거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d15_coffee', 3, NULL, NULL, NULL, 'Pastries for the team on a Monday? Somebody must have done something right.', '월요일에 팀 간식이라니요? 누가 뭘 제대로 해냈나 봐요.', 'Tell her what you''re celebrating, and make it about the team.', '무엇을 축하하는지 말하되, 팀의 공으로 돌리세요.', '[]', 'They did. We signed a big client on Friday, and the team worked hard for it.', '맞아요. 금요일에 큰 고객사와 계약했는데, 팀이 정말 고생했거든요.', '["They did. We signed a big client this morning, and the team worked hard for it.","Somebody did: me. I closed a big deal on Friday, pretty much on my own.","Not really. It''s just a gray Monday, and I figured everyone could use a treat."]', '["맞아요. 오늘 아침에 큰 고객사와 계약했는데, 팀이 정말 고생했거든요.","누가 해냈냐면, 저요. 금요일에 큰 계약을 거의 혼자 따냈어요.","딱히요. 그냥 흐린 월요일이라, 다들 단 게 필요할 것 같아서요."]', '["This morning? It''s not even eight yet. You people start early.","Ha. And the team gets muffins for that?","Fair enough. But you look way too happy for just a Monday."]', '["오늘 아침에요? 아직 여덟 시도 안 됐는데요. 일찍들 시작하네요.","하. 그런데 그걸로 팀이 머핀을 받는다고요?","그럴 수도 있죠. 그런데 그냥 월요일치고는 너무 신나 보이는데요."]', NULL, 'Congratulations! Then the team deserves the good stuff. How many do you need?', '축하해요! 그럼 팀은 좋은 걸 먹어야죠. 몇 개 필요해요?'),
  ('pr_d15_coffee', 4, NULL, NULL, NULL, 'I''ve got plenty of both.', '둘 다 넉넉히 있어요.', 'Order six pastries, three of each kind.', '빵 여섯 개를 두 종류 세 개씩 주문하세요.', '[]', 'Let''s do half a dozen. Three muffins and three croissants, please.', '여섯 개 주세요. 머핀 세 개, 크루아상 세 개요.', '["Let''s do a dozen. Six muffins and six croissants, please.","Let''s do half a dozen. Five muffins and just one croissant, please.","Just give me whatever didn''t sell yesterday. They won''t notice."]', '["열두 개 주세요. 머핀 여섯 개, 크루아상 여섯 개요.","여섯 개 주세요. 머핀 다섯 개, 크루아상은 한 개만요.","어제 안 팔린 걸로 아무거나 주세요. 다들 모를 거예요."]', '["A dozen? That''s my whole tray. How big is this team?","Five and one? Somebody''s going to fight over that croissant.","Yesterday''s? For a celebration? I don''t think so."]', '["열두 개요? 그럼 쟁반이 다 비어요. 팀이 몇 명이에요?","다섯이랑 하나요? 크루아상 하나 두고 싸움 나겠네요.","어제 거요? 축하하는 날에요? 그건 안 되죠."]', NULL, 'Three and three, boxed up. With your latte, that''s twenty-five seventy-five, so twenty-seven eighty-seven with tax.', '세 개씩, 상자에 담았어요. 라테까지 25달러 75센트, 세금 포함해서 27달러 87센트예요.'),
  ('pr_d15_standup', 1, NULL, 'Nine thirty at the team desks. Jun is back for the first time since Wednesday.', '아홉 시 반, 팀 자리입니다. 준이 수요일 이후 처음으로 돌아왔습니다.', 'Hey, look who''s back! The man who closed Summit Retail.', '어, 누가 돌아왔나 보세요! 서밋 리테일 계약을 따낸 주인공이요.', 'Start the meeting, welcome Jun back, and have him give his trip update before anyone else.', '회의를 시작하고, 준을 반갑게 맞이하고, 다른 사람보다 먼저 출장 이야기를 하게 하세요.', '[]', 'Welcome back, Jun! Let''s get started. Why don''t you go first and tell us about the trip?', '돌아온 걸 환영해요, 준! 시작하죠. 준이 먼저 출장 얘기를 해 줄래요?', '["Welcome back, Jun! How was your week in Ridgeport? Why don''t you go first?","Okay, let''s get started. Derek, why don''t you go first, and Jun, you can go last today?","Welcome back, Jun! Take all the time you need today. Tell us everything, start to finish."]', '["돌아온 걸 환영해요, 준! 리지포트에서 일주일은 어땠어요? 준이 먼저 해 줄래요?","자, 시작하죠. 데릭이 먼저 하고, 준은 오늘 마지막에 해요.","돌아온 걸 환영해요, 준! 오늘은 시간 얼마든지 써요. 처음부터 끝까지 다 얘기해 줘요."]', '["A week? He was gone two days, Priya. Felt longer to me, though.","Me first? I figured you''d want the big news first.","Everything? Careful, Priya. That''s how a standup turns into lunch."]', '["일주일이요? 이틀 갔다 왔어요, 프리야. 저한텐 더 길게 느껴졌지만요.","저부터요? 큰 소식부터 들을 줄 알았는데요.","전부요? 조심해요, 프리야. 그러다 스탠드업이 점심시간까지 가요."]', 'jun', 'Thanks! Short version: Greg signed on Friday, phase one kicks off next week, and the dashboard is due November first.', '고마워요! 짧게 말하면, 금요일에 그렉이 서명했고, 1단계는 다음 주에 시작하고, 대시보드 마감은 11월 1일이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d15_standup', 2, 'jun', 'Jun is on a roll. The short version is getting longer.', '준은 신이 났습니다. 짧은 버전이 점점 길어집니다.', 'Oh, and the hotel had this amazing breakfast, and the shuttle driver told me all about Ridgeport, and—', '아, 그리고 호텔 조식이 정말 끝내줬고, 셔틀 기사님이 리지포트 얘기를 엄청 해 주셨는데, 그리고…', 'Stop him kindly: the stories can wait. Move him on to what''s in his way this week.', '부드럽게 끊으세요. 그 이야기는 기다릴 수 있습니다. 이번 주에 막히는 게 있는지로 넘어가세요.', '[]', 'I want to hear it all, but let''s save the stories for lunch. Anything blocking you this week?', '다 듣고 싶은데, 그 얘기는 점심때 하죠. 이번 주에 막히는 거 있어요?', '["Jun, this is a standup, not a travel blog. Just tell us what you''re working on.","I want to hear it all, but let''s save the stories for lunch. So, how was your flight back home?","Sounds amazing! Keep going, we''ve got time. What else did you get to do in Ridgeport?"]', '["준, 이건 스탠드업이지 여행 블로그가 아니에요. 무슨 일 하고 있는지만 말해요.","다 듣고 싶은데, 그 얘기는 점심때 하죠. 돌아오는 비행기는 어땠어요?","재밌네요! 계속해요, 시간 있어요. 리지포트에서 또 뭐 했어요?"]', '["Oh. Sorry. I guess I got a little carried away.","The flight? Bumpy, but... wait, didn''t you just say to save the stories?","Okay! So on Thursday night, I found this little taco place, and—"]', '["아. 죄송해요. 제가 좀 신이 났었나 봐요.","비행기요? 좀 흔들렸는데… 잠깐, 방금 얘기는 나중에 하자고 하지 않았어요?","좋아요! 그러니까 목요일 밤에 작은 타코집을 발견했는데요, 그게…"]', 'jun', 'Right, sorry. Just one thing: I need to file my trip expenses, and I''ve never done it here.', '맞아요, 죄송해요. 하나만요. 출장 경비를 처리해야 하는데, 여기서 한 번도 안 해 봤어요.'),
  ('pr_d15_standup', 3, 'jun', NULL, NULL, 'Who do I give my receipts to?', '영수증은 누구한테 내면 돼요?', 'Send him to the person who handles expenses, and tell him what to bring.', '경비를 담당하는 사람에게 보내고, 무엇을 가져가야 하는지 알려 주세요.', '[]', 'Linda in HR handles that. Bring her your receipts, and she''ll walk you through the form.', '그건 인사팀 린다가 맡아요. 영수증을 가져가면 양식 쓰는 걸 차근차근 알려 줄 거예요.', '["Tom at the front desk handles that. Bring him your receipts, and he''ll walk you through it.","Just hang on to them for now. We usually do all the expenses at the end of the quarter.","Linda in HR handles that. Don''t worry about the receipts. She just needs the total."]', '["그건 안내 데스크 톰이 맡아요. 영수증을 가져가면 차근차근 알려 줄 거예요.","일단 그냥 갖고 있어요. 경비는 보통 분기 말에 한꺼번에 처리해요.","그건 인사팀 린다가 맡아요. 영수증은 신경 쓰지 마요. 총액만 있으면 돼요."]', '["Tom? I thought he did badges and meeting rooms.","The end of the quarter? That''s a lot of money to wait for.","No receipts? Really? That sounds almost too easy."]', '["톰이요? 톰은 출입증이랑 회의실 담당인 줄 알았는데요.","분기 말이요? 기다리기엔 꽤 큰돈인데요.","영수증 없이요? 정말요? 너무 쉬운데요."]', 'jun', 'Linda. Got it. I''ll stop by today.', '린다요. 알겠어요. 오늘 들를게요.'),
  ('pr_d15_standup', 4, NULL, 'Derek''s turn. While Jun was away, Derek took over a bug with the store IDs.', '데릭 차례입니다. 준이 없는 동안 데릭이 매장 ID 버그를 맡았습니다.', 'My update: I picked up Jun''s store ID bug while he was out. It''s fixed and live.', '제 업데이트요. 준이 없는 동안 매장 ID 버그를 맡았어요. 고쳐서 배포까지 했어요.', 'Thank him for stepping in, and ask whether it belongs in this week''s update to the client.', '대신 맡아 준 데 고마워하고, 이번 주에 고객에게 보내는 업데이트에 넣어야 할지 물어보세요.', '[]', 'Thanks for covering, Derek. Should we mention it in Friday''s status report to Greg?', '대신 맡아 줘서 고마워요, 데릭. 금요일에 그렉한테 보내는 현황 보고에 넣을까요?', '["Thanks for covering, Derek. Is this the same gift card bug we had last week?","Thanks, Derek. Jun, next time, please hand off your bugs before you leave on a trip.","Great, thanks. I''ll tell Greg we haven''t had a single bug since the contract."]', '["대신 맡아 줘서 고마워요, 데릭. 지난주 그 기프트 카드 버그랑 같은 거예요?","고마워요, 데릭. 준, 다음엔 출장 가기 전에 버그를 꼭 넘기고 가요.","좋아요, 고마워요. 그렉한테는 계약 이후로 버그가 하나도 없었다고 할게요."]', '["Different bug. The gift cards are behind us, knock on wood.","Hey, he did hand it off. It was right there on the board.","Not a single one? I wouldn''t put that in writing."]', '["다른 버그예요. 기프트 카드 건은 이제 끝났어요, 제발요.","에이, 준은 넘기고 갔어요. 보드에 다 올라와 있었어요.","하나도요? 저라면 그건 글로 안 남겨요."]', NULL, 'Worth one line. It''s fixed, so it''s good news.', '한 줄 정도면 좋겠네요. 고쳤으니까 좋은 소식이고요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d15_standup', 5, NULL, 'Fourteen minutes so far. Your meetings end on time.', '지금까지 14분. 당신의 회의는 제시간에 끝납니다.', 'That''s it from me. Anything else before we break?', '저는 이게 다예요. 끝내기 전에 더 있어요?', 'Remind everyone when phase one starts, say you''ll send the meeting invite yourself today, and close the standup.', '1단계가 언제 시작하는지 다시 알리고, 오늘 직접 회의 초대를 보내겠다고 하고, 스탠드업을 마치세요.', '[]', 'Just one thing: phase one kicks off next week. I''ll send the invite today. Thanks, everyone!', '하나만요. 1단계는 다음 주에 시작해요. 초대는 오늘 보낼게요. 다들 고마워요!', '["Just one thing: phase one kicks off tomorrow. I''ll send the invite tonight. Thanks, everyone!","One more thing. Let''s walk through the whole phase one plan right now, while we''re all here.","Just one thing: phase one kicks off next week. Derek, could you send everyone the invite?"]', '["하나만요. 1단계는 내일 시작해요. 초대는 오늘 밤에 보낼게요. 다들 고마워요!","하나 더요. 다 모인 김에 지금 1단계 계획을 처음부터 끝까지 훑어보죠.","하나만요. 1단계는 다음 주에 시작해요. 데릭, 다들한테 초대 좀 보내 줄래요?"]', '["Tomorrow? Jun just said next week. Did I miss an email?","Now? We''re at fourteen minutes, Priya. You never go over.","Me? Scheduling''s your superpower, not mine."]', '["내일요? 준은 방금 다음 주라던데요. 제가 메일을 놓쳤나요?","지금요? 벌써 14분이에요, 프리야. 시간 넘긴 적 없잖아요.","저요? 일정 잡는 건 프리야 특기잖아요. 제 특기가 아니고요."]', NULL, 'Fifteen minutes on the dot. Some things never change.', '딱 15분. 변하지 않는 것도 있네요.'),
  ('pr_d15_applicants', 1, NULL, 'Monday afternoon in HR. Linda waves you in, mug in hand.', '월요일 오후, 인사팀입니다. 린다가 머그잔을 든 채 들어오라고 손짓합니다.', 'Priya! The posting went live this morning, and we already have twenty-three applications.', '프리야! 공고가 오늘 아침에 올라갔는데, 벌써 지원서가 스물세 개나 들어왔어요.', 'Show you are pleased, and ask who looks at the applications first.', '반가워하고, 지원서를 누가 먼저 보는지 물어보세요.', '[]', 'Twenty-three already? That''s great. Who does the first pass on the resumes?', '벌써 스물세 개요? 잘됐네요. 이력서는 누가 먼저 걸러요?', '["Twenty-three already? Great. Can you forward all of them to Derek by tonight?","Only twenty-three? I honestly thought we''d have a lot more by now.","Twenty-three already? That''s great. So when does the new developer start?"]', '["벌써 스물세 개요? 좋네요. 오늘 밤에 전부 데릭한테 넘겨 줄 수 있어요?","겨우 스물세 개요? 솔직히 지금쯤이면 훨씬 많을 줄 알았어요.","벌써 스물세 개요? 잘됐네요. 그럼 새 개발자는 언제 출근해요?"]', '["All twenty-three? To Derek? He''d never forgive us.","It''s been six hours, Priya. That''s actually a lot.","Start? We haven''t even read a resume yet!"]', '["스물세 개 전부요? 데릭한테요? 우릴 절대 용서 안 할걸요.","여섯 시간 지났어요, 프리야. 사실 많은 거예요.","출근이요? 아직 이력서 한 장도 안 읽었는데요!"]', NULL, 'I do a quick screen for the basics. Then I send you the best five or six.', '제가 기본 조건만 빠르게 걸러요. 그다음에 제일 괜찮은 대여섯 명을 보내 드려요.'),
  ('pr_d15_applicants', 2, NULL, 'Phase one starts next week, and Derek''s days are already full.', '다음 주에 1단계가 시작되고, 데릭의 일정은 이미 꽉 찼습니다.', 'After that comes a thirty-minute phone screen. Should I set those up with you and Derek?', '그다음엔 30분짜리 전화 면접이 있어요. 프리야랑 데릭으로 잡을까요?', 'Take the phone screens on yourself, and keep Derek for the technical round later.', '전화 면접은 당신이 맡고, 데릭은 나중에 기술 면접에 들어가게 하세요.', '[]', 'Just me for the phone screens. Derek has phase one, so let''s save him for the technical interview.', '전화 면접은 저 혼자 할게요. 데릭은 1단계가 있으니까, 기술 면접 때 들어오게 해요.', '["Just Derek for the phone screens. I''m busy with phase one, so I''ll join for the final round.","Let''s skip the phone screens. Just bring the best ones straight in for a full day of interviews instead.","Both of us, please. Derek will make the time, even if phase one has to wait a few days."]', '["전화 면접은 데릭 혼자 하게 해요. 저는 1단계로 바빠서 최종 면접에 들어갈게요.","전화 면접은 건너뛰죠. 제일 괜찮은 사람들만 바로 불러서 대신 하루 종일 면접 봐요.","둘 다 넣어 주세요. 1단계가 며칠 밀리더라도 데릭이 시간을 낼 거예요."]', '["Derek on his own? I heard he''s buried in phase one.","A full day for each of them? That''s a lot of everyone''s time.","Phase one waits? I don''t think Maya would love that."]', '["데릭 혼자요? 1단계 일에 파묻혀 있다던데요.","한 명마다 하루씩이요? 다들 시간을 너무 많이 써요.","1단계를 미룬다고요? 마야가 좋아할 것 같진 않은데요."]', NULL, 'Smart. Engineers hate losing an afternoon to phone calls.', '현명하네요. 개발자들은 전화로 오후를 날리는 걸 질색하거든요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d15_applicants', 3, NULL, 'The team works in the office. Maya is the hiring manager.', '팀은 사무실에서 일합니다. 채용 책임자는 마야입니다.', 'One question keeps coming up. A lot of applicants want to know if the job is remote.', '자꾸 나오는 질문이 하나 있어요. 지원자가 많이들 재택근무가 되냐고 물어요.', 'Say how the team works today, and leave any exceptions to the person who decides.', '팀이 지금 어떻게 일하는지 말하고, 예외는 결정권자에게 맡기세요.', '[]', 'It''s in the office for now. If a great candidate needs flexibility, let''s ask Maya. It''s her call.', '지금은 사무실 근무예요. 좋은 지원자가 유연 근무가 필요하면 마야에게 물어봐요. 마야가 정할 일이니까요.', '["Just tell them it''s fully remote. We''ll get a lot more applicants, and we can sort it out later.","It''s in the office for now. If a great candidate needs flexibility, I''ll just decide it case by case.","Good question. Tell them the range is ninety-five to one fifteen, plus benefits."]', '["완전 재택이라고 해요. 지원자가 훨씬 많아질 거고, 나중에 정리하면 돼요.","지금은 사무실 근무예요. 좋은 지원자가 유연 근무가 필요하면 제가 그때그때 정할게요.","좋은 질문이에요. 연봉 범위는 9만 5천에서 11만 5천에 복리후생 별도라고 해요."]', '["And then they show up expecting to work from home? No, thanks.","You? I thought Maya was the hiring manager on this one.","That''s already in the posting. I was asking about remote."]', '["그러다 재택인 줄 알고 들어오면요? 그건 안 돼요.","프리야가요? 이번 채용 책임자는 마야인 줄 알았는데요.","그건 공고에 이미 있어요. 재택을 물어본 건데요."]', NULL, 'In the office, and Maya decides exceptions. I''ll put that in my reply template.', '사무실 근무, 예외는 마야가 결정. 답장 양식에 그렇게 넣을게요.'),
  ('pr_d15_applicants', 4, NULL, NULL, NULL, 'Maya also mentioned a contractor. Is that still happening?', '마야가 계약직 얘기도 했는데요. 그것도 그대로 진행해요?', 'Confirm it is, and find out how bringing in a contractor works here.', '진행한다고 확인하고, 여기서는 계약직을 어떻게 구하는지 알아보세요.', '[]', 'Yes, that''s the other half of the plan. Does that go through you, or do we use an agency?', '네, 그게 계획의 나머지 절반이에요. 그건 린다를 거쳐요, 아니면 에이전시를 써요?', '["No, Maya dropped the contractor idea on Friday. It''s just the one full-time position now.","Yes, it is. Could you post it next to the full-time job, with the same salary range?","Yes, and I already promised a friend of mine the job. Can you send her the paperwork?"]', '["아뇨, 마야가 금요일에 계약직은 없던 걸로 했어요. 이제 정규직 한 자리뿐이에요.","네, 진행해요. 정규직 공고 옆에 같은 연봉 범위로 올려 줄 수 있어요?","네, 그리고 제 친구한테 벌써 그 자리를 약속했어요. 친구한테 서류 좀 보내 줄래요?"]', '["Really? Her email on Friday said both. I''ll double-check with her.","Contractors don''t really work that way. They''re paid by the hour.","Whoa. Let''s not promise anything to anyone just yet."]', '["그래요? 금요일 메일에는 둘 다라고 돼 있었는데요. 마야한테 다시 확인할게요.","계약직은 보통 그렇게 안 해요. 시간당으로 받거든요.","워워. 아직 누구한테도 약속하진 말죠."]', NULL, 'We use an agency. I''ll send you their contact. They can usually have someone here in two weeks.', '에이전시를 써요. 연락처 보내 드릴게요. 보통 2주면 사람을 보내 줘요.'),
  ('pr_d15_applicants', 5, NULL, 'Your mornings this week are mostly client calls.', '이번 주 오전은 대부분 고객 통화입니다.', 'Last thing. When are you free for the first phone screens?', '마지막으로요. 첫 전화 면접은 언제 시간 돼요?', 'Offer her the end of the week, after lunch, and say why not earlier in the day.', '이번 주 후반 점심 이후로 제안하고, 왜 더 이른 시간은 안 되는지 말하세요.', '[]', 'Thursday or Friday afternoon works best. My mornings are mostly client calls.', '목요일이나 금요일 오후가 제일 좋아요. 오전엔 거의 고객 통화가 있어서요.', '["Thursday or Friday morning works best. My afternoons are mostly client calls.","Anytime at all. Just put them on my calendar, and I''ll move things around.","Not this week. Let''s wait until phase one is done, sometime in November."]', '["목요일이나 금요일 오전이 제일 좋아요. 오후엔 거의 고객 통화가 있어서요.","아무 때나 괜찮아요. 그냥 제 캘린더에 넣어 주면 제가 다른 걸 옮길게요.","이번 주는 안 돼요. 1단계가 끝나는 11월쯤까지 기다리죠."]', '["Mornings? Huh. I had you down as busy before lunch.","Anytime? Even on top of your client calls?","November? You told me you needed someone in six weeks."]', '["오전이요? 어라, 점심 전엔 바쁜 걸로 알고 있었는데요.","아무 때나요? 고객 통화랑 겹쳐도요?","11월이요? 6주 안에 사람이 필요하다고 했잖아요."]', NULL, 'Thursday and Friday afternoons. I''ll start booking them. Now comes the fun part!', '목요일, 금요일 오후요. 바로 잡기 시작할게요. 이제부터가 재밌는 부분이에요!');
REPLACE INTO calendar (day, time, title, title_ko, place, episode, hero) VALUES
  (15, '09:30', 'Monday standup: Jun is back', '월요일 스탠드업: 준 복귀', 'office_desk_team', NULL, 'derek'),
  (15, '11:00', 'Catch up with Jun: the store ID fix', '준과 근황 나누기: 매장 ID 수정', 'office_desk', 'dk_d15_back', 'derek'),
  (15, '14:30', 'Ask Maya about your comp time', '마야에게 보상 휴가 요청', 'office_manager', 'dk_d15_comp_time', 'derek'),
  (15, '18:45', 'Return Carl''s cooler', '칼에게 아이스박스 돌려주기', 'apartment_door', 'dk_d15_carl', 'derek'),
  (15, '09:30', 'Daily standup: Jun is back', '데일리 스탠드업: 준 복귀', 'office_desk_team', 'pr_d15_standup', 'priya'),
  (15, '11:00', 'Send the phase one kickoff invite', '1단계 킥오프 초대 보내기', 'office_desk_priya', NULL, 'priya'),
  (15, '15:00', 'Hiring: first applicants with Linda', '채용: 린다와 첫 지원자 검토', 'office_hr', 'pr_d15_applicants', 'priya');
